<main class="partner-public">
<section class="partner-public-hero"><div><span class="partner-badge"><?=e($partner['partner_type'])?></span><h1><?=e($partner['name'])?> <?= $partner['verified']?'✓':''?></h1><p><?=e($partner['description'])?></p><div class="hero-actions"><a class="btn btn-primary" href="https://wa.me/<?=e(preg_replace('/\D/','',$partner['whatsapp']))?>" target="_blank">Falar no WhatsApp</a><a class="btn btn-soft" href="https://www.google.com/maps/search/?api=1&query=<?=urlencode($partner['address'].' '.$partner['city'])?>" target="_blank">Como chegar</a></div></div><div class="partner-summary"><b>⭐ <?=e($partner['rating'])?></b><span><?=e($partner['city'])?> / <?=e($partner['state'])?></span><?php if($partner['emergency_24h']):?><span class="status success">Atendimento 24h</span><?php endif;?></div></section>
<?php if($offers):?><section class="section compact"><div class="offer-row"><?php foreach($offers as $offer):?><article class="offer-card"><span>🎁 Oferta</span><h3><?=e($offer['title'])?></h3><p><?=e($offer['description'])?></p><b><?=e($offer['coupon_code'])?></b></article><?php endforeach;?></div></section><?php endif;?>
<?php if($services):?><section class="section compact"><div class="section-heading left"><h2>Serviços</h2></div><div class="service-grid"><?php foreach($services as $service):?><article class="service-card"><h3><?=e($service['name'])?></h3><p><?=e($service['description'])?></p><b><?=money($service['price_cents'])?></b><span><?=e($service['duration_minutes'])?> min</span><?php if($ownerPets):?><form method="post" action="<?=url('/owner/services/'.$service['id'].'/book')?>" class="booking-mini"><?=csrf_field()?><select name="pet_id"><?php foreach($ownerPets as $op):?><option value="<?=e($op['id'])?>"><?=e($op['name'])?></option><?php endforeach;?></select><input type="datetime-local" name="scheduled_at" required><input name="notes" placeholder="Observação opcional"><button class="btn btn-primary btn-block">Solicitar reserva</button></form><?php elseif(!Auth::user()):?><a class="btn btn-soft btn-block" href="<?=url('/login')?>">Entrar para reservar</a><?php endif;?></article><?php endforeach;?></div></section><?php endif;?>
<?php if($partner['partner_type']==='HOTEL' && $hotelUnits):?><section class="section compact"><div class="section-heading left"><h2>Hospedagem para quem é da família</h2><p>Solicite uma estadia e compartilhe os dados essenciais do seu pet com segurança.</p></div><div class="service-grid"><?php foreach($hotelUnits as $unit):?><article class="service-card"><h3><?=e($unit['name'])?></h3><p><?=e($unit['description'])?></p><b><?=money($unit['daily_price_cents'])?>/dia</b><span>Capacidade <?=e($unit['capacity'])?> · <?=e($unit['pet_size'])?></span><?php if($ownerPets):?><form method="post" action="<?=url('/owner/hotel/'.$unit['id'].'/book')?>" class="booking-mini"><?=csrf_field()?><select name="pet_id"><?php foreach($ownerPets as $op):?><option value="<?=e($op['id'])?>"><?=e($op['name'])?></option><?php endforeach;?></select><div class="form-grid"><label>Entrada<input type="date" name="check_in" required></label><label>Saída<input type="date" name="check_out" required></label></div><input name="notes" placeholder="Cuidados, rotina e observações"><button class="btn btn-primary btn-block">Solicitar hospedagem</button></form><?php elseif(!Auth::user()):?><a class="btn btn-soft btn-block" href="<?=url('/login')?>">Entrar para reservar</a><?php endif;?></article><?php endforeach;?></div></section><?php endif;?>
<?php if($partner['partner_type']==='RESTAURANT'):?><section class="section compact"><div class="section-heading left"><h2>Reserve uma mesa na área pet</h2><p>Uma experiência para a família inteira, com espaço pensado também para as patas.</p></div><article class="panel-card narrow"><?php if($ownerPets):?><form method="post" action="<?=url('/owner/restaurant/'.$partner['id'].'/book')?>" class="booking-mini"><?=csrf_field()?><label>Pet<select name="pet_id"><option value="">Sem pet vinculado</option><?php foreach($ownerPets as $op):?><option value="<?=e($op['id'])?>"><?=e($op['name'])?></option><?php endforeach;?></select></label><label>Data e horário<input type="datetime-local" name="reserved_at" required></label><label>Pessoas<input type="number" name="guests" min="1" value="2"></label><label>Observações<input name="notes" placeholder="Mesa tranquila, água, espaço para carrinho..."></label><button class="btn btn-primary btn-block">Solicitar reserva</button></form><?php elseif(!Auth::user()):?><a class="btn btn-soft btn-block" href="<?=url('/login')?>">Entrar para reservar</a><?php endif;?></article></section><?php endif;?>
<?php if($products):?><section class="section compact"><div class="section-heading left"><h2>Produtos</h2></div><div class="product-grid"><?php foreach($products as $product):?><article class="product-card"><div class="product-image"><?php if($product['main_image_path']):?><img src="<?=asset($product['main_image_path'])?>" alt=""><?php else:?>🛍<?php endif;?></div><span><?=e($product['category'])?></span><h3><?=e($product['name'])?></h3><p><?=e($product['description'])?></p><strong><?=money($product['promotional_price_cents']?:$product['price_cents'])?></strong><a class="btn btn-soft btn-block" target="_blank" href="https://wa.me/<?=e(preg_replace('/\D/','',$partner['whatsapp']))?>?text=<?=urlencode('Olá! Vi o produto '.$product['name'].' no PetPass e gostaria de saber mais.')?>">Consultar no WhatsApp</a></article><?php endforeach;?></div></section><?php endif;?>
